"use client";

import { useState } from 'react';
import { Sidebar } from '@/components/sidebar';
import { useAppStore } from '@/lib/store';
import { ComicUploadForm } from '@/components/comic-upload-form';
import { ComicModal } from '@/components/comic-modal';
import { Plus, ArrowLeft, User, Tag, Clock } from 'lucide-react';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import type { Comic } from '@/lib/types';
import { useParams } from 'next/navigation';

export default function ShortComicsCategoryPage() {
  const params = useParams();
  const categoryParam = params.category as string;
  const { comics, isAdmin, removeComic, categories } = useAppStore();
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [selectedComic, setSelectedComic] = useState<Comic | null>(null);

  const formatComicDate = (comic: Comic) => {
    const sourceDate = comic.updatedAt ?? comic.createdAt;
    return sourceDate ? sourceDate.split('T')[0] : '날짜 없음';
  };

  const currentCategoryObj = categories.find(c => c.id === categoryParam);
  const categoryTitle = currentCategoryObj ? currentCategoryObj.label : '웹툰/개인작';

  // 특정 카테고리에 속한 short 코믹들
  const categoryComics = comics.filter(c => c.type === 'short' && c.category === categoryParam);
  const latestComic = categoryComics[categoryComics.length - 1];

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('정말로 이 만화를 삭제하시겠습니까?')) {
      removeComic(id);
    }
  };

  return (
    <div className="min-h-screen bg-[#fcfcfc] dark:bg-background">
      <Sidebar />
      
      <main className="min-h-screen transition-all duration-300 pt-16 lg:pt-0 pb-20">
        {/* Kakao Page Style Header Background */}
        <div className="relative h-64 w-full overflow-hidden bg-slate-900 lg:h-80">
          {latestComic && (
            <div className="absolute inset-0">
              <img 
                src={latestComic.thumbnailUrl} 
                alt="header-bg" 
                className="h-full w-full object-cover blur-2xl opacity-40 brightness-50"
              />
              <div className="absolute inset-0 bg-gradient-to-t from-[#fcfcfc] dark:from-background via-transparent" />
            </div>
          )}
        </div>

        <div className="mx-auto -mt-48 max-w-6xl px-4 sm:px-6 relative z-10">
          <Link href="/comics/short" className="mb-6 inline-flex items-center text-sm font-medium text-white/80 hover:text-white transition-colors">
            <ArrowLeft className="mr-2 h-4 w-4" />
            전체 목록으로
          </Link>

          <div className="flex flex-col gap-8 lg:flex-row">
            {/* Left: Info Card (Kakao Style Cover) */}
            <div className="w-full lg:w-[280px] shrink-0">
              <div className="overflow-hidden rounded-xl border border-border/10 bg-white dark:bg-muted shadow-2xl">
                <div className="aspect-[3/4] w-full relative">
                  <img
                    src={latestComic?.thumbnailUrl || "https://via.placeholder.com/300x400"}
                    alt={categoryTitle}
                    className="h-full w-full object-cover"
                  />
                </div>
                <div className="p-5">
                  <h1 className="text-xl font-black tracking-tight text-slate-900 dark:text-white">
                    {categoryTitle}
                  </h1>
                  <div className="mt-3 space-y-2">
                    <div className="flex items-center gap-2 text-sm">
                      <User className="h-4 w-4 text-slate-400" />
                      <span className="font-bold text-slate-700 dark:text-slate-300">JYAMONG</span>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-slate-500">
                      <Tag className="h-4 w-4" />
                      <span>{latestComic ? '웹툰/만화' : '작품 준비 중'}</span>
                    </div>
                    <div className="flex items-center gap-2 text-sm text-slate-500">
                      <Clock className="h-4 w-4" />
                      <span>{categoryComics.length}개 에피소드</span>
                    </div>
                  </div>
                  
                  {isAdmin && (
                    <Button 
                      className="mt-6 w-full font-bold shadow-lg" 
                      onClick={() => setShowUploadForm(!showUploadForm)}
                    >
                      <Plus className="mr-2 h-4 w-4" />
                      에피소드 업로드
                    </Button>
                  )}
                </div>
              </div>
            </div>

            {/* Right: Episode List */}
            <div className="flex-1">
              <div className="bg-white dark:bg-muted rounded-xl border border-border shadow-sm p-1">
                <div className="flex items-center justify-between px-6 py-4 border-b border-border">
                  <span className="text-sm font-bold text-slate-900 dark:text-white">전체 ({categoryComics.length})</span>
                </div>

                <div className="divide-y divide-border">
                  {categoryComics.slice().reverse().map((comic, idx) => (
                    <div 
                      key={comic.id}
                      onClick={() => setSelectedComic(comic)}
                      className="group flex items-center gap-4 px-6 py-4 hover:bg-slate-50 dark:hover:bg-slate-800/50 cursor-pointer transition-colors"
                    >
                      <div className="relative w-24 aspect-[4/3] rounded-md overflow-hidden bg-slate-100 shrink-0 border border-border/50">
                        <img 
                          src={comic.thumbnailUrl || "https://via.placeholder.com/300x400"} 
                          alt={comic.title}
                          className="w-full h-full object-cover transition-transform group-hover:scale-105"
                        />
                      </div>
                      
                      <div className="flex-1 min-w-0">
                        <h3 className="font-bold text-slate-800 dark:text-slate-200 line-clamp-1 group-hover:text-blue-600 transition-colors">
                          {comic.title}
                        </h3>
                        <div className="mt-1 flex items-center gap-3 text-[12px] text-slate-500">
                          <span>{formatComicDate(comic)}</span>
                          <span className="w-0.5 h-0.5 rounded-full bg-slate-300"></span>
                          <span>{comic.images.length}p</span>
                        </div>
                      </div>

                      {isAdmin && (
                        <Button
                          variant="ghost"
                          size="icon"
                          className="opacity-0 group-hover:opacity-100 text-destructive hover:bg-destructive/10"
                          onClick={(e) => handleDelete(e, comic.id)}
                        >
                          <Plus className="h-4 w-4 rotate-45" />
                        </Button>
                      )}
                    </div>
                  ))}
                  
                  {categoryComics.length === 0 && (
                    <div className="py-20 text-center text-slate-400">
                      등록된 에피소드가 없습니다.
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>

        {showUploadForm && (
          <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-4 overflow-y-auto">
            <div className="bg-background w-full max-w-2xl rounded-2xl shadow-2xl relative my-8">
              <Button 
                variant="ghost" 
                size="icon" 
                className="absolute right-4 top-4 z-10" 
                onClick={() => setShowUploadForm(false)}
              >
                <Plus className="h-6 w-6 rotate-45" />
              </Button>
              <div className="p-8">
                <h2 className="text-2xl font-black mb-6">에피소드 업로드</h2>
                <ComicUploadForm 
                  onSuccess={() => setShowUploadForm(false)} 
                  initialType="short"
                  initialCategory={categoryParam}
                />
              </div>
            </div>
          </div>
        )}

        {selectedComic && (
          <ComicModal
            comic={selectedComic}
            isOpen={!!selectedComic}
            onClose={() => setSelectedComic(null)}
          />
        )}
      </main>
    </div>
  );
}
